    static void Set(object o,string n,object v){var t=o.GetType();var f=t.GetField(n,BindingFlags.Instance|BindingFlags.NonPublic);if(f!=null)f.SetValue(o,v);else t.GetProperty(n).GetSetMethod(true).Invoke(o,new[]{v});}
    static async Task Wait(float seconds){var until=DateTime.UtcNow.AddSeconds(seconds);while(DateTime.UtcNow<until)await Task.Delay(16);}
    static void Quiet(FastingTopDownGame g){g.Begin();foreach(var e in g.entities)e.gameObject.SetActive(false);Set(g,"wave",float.MaxValue);}
    public static async Task<string> Run()
    {
        var g=UnityEngine.Object.FindAnyObjectByType<FastingTopDownGame>();var ui=UnityEngine.Object.FindAnyObjectByType<FastingPortraitHUD>();if(!Application.isPlaying||!g||!ui)throw new Exception("Play updated scene");int count=0;var log=new System.Text.StringBuilder();Action<bool,string> check=(ok,s)=>{if(!ok)throw new Exception("FAIL: "+s);count++;log.AppendLine("PASS: "+s);};Keyboard keyboard=null;Key? held=null;var oldBackground=InputSystem.settings.backgroundBehavior;var oldMode=InputSystem.settings.editorInputBehaviorInPlayMode;Action queue=()=>{if(keyboard!=null)InputSystem.QueueStateEvent(keyboard,held.HasValue?new KeyboardState(held.Value):new KeyboardState());};Action current=()=>{if(keyboard!=null)keyboard.MakeCurrent();};
        try{
            g.enabled=false;Quiet(g);UnityEngine.Canvas.ForceUpdateCanvases();check(ui.ring.GetComponent<CanvasRenderer>()!=null&&ui.ring.canvasRenderer.GetMesh().vertexCount>0,"Portrait fire ring has actual rendered geometry");check(ui.fireFrames.All(s=>UnityEditor.AssetDatabase.GetAssetPath(s)=="Assets/Sprite/Effect/Fire-Sheet.png"),"Transparent fire sheet drives fever effect");check(g.settings.waveIntervals.SequenceEqual(new[]{2.4f,2f,1.7f,1.4f}),"Higher hazard frequency saved");check(g.settings.DropChance(FastingTopDownEntity.Kind.Book)==.03f&&g.settings.DropChance(FastingTopDownEntity.Kind.Page)==.08f&&g.settings.DropChance(FastingTopDownEntity.Kind.Fragment)==.1f,"Scripture drops lowered independently");
            float[] speeds={2.5f,2.75f,3,3.25f};for(int i=0;i<4;i++){Quiet(g);Set(g,"StageIndex",i);float before=g.gameCamera.transform.position.y;g.Tick(.1f,Vector2.zero);check(Mathf.Abs(g.CurrentSpeed-speeds[i])<.001f&&Mathf.Abs(g.gameCamera.transform.position.y-before-speeds[i]*.1f)<.001f,"Camera speed increases by stage "+(i+1));}
            Quiet(g);g.player.position=new Vector3(0,3);float y=g.player.position.y;g.Tick(.1f,Vector2.up);check(g.player.position.y-y>g.CurrentSpeed*.1f,"Up input moves ahead of camera");y=g.player.position.y;float cam=g.gameCamera.transform.position.y;g.Tick(.1f,Vector2.down);check(g.player.position.y<y&&g.gameCamera.transform.position.y>cam,"Down input moves backwards while camera keeps advancing");g.Tick(.1f,Vector2.right);check(g.player.position.x>0&&g.player.position.x<3,"Right movement is continuous rather than lane teleport");g.Tick(.1f,Vector2.left);check(Mathf.Abs(g.player.position.x)<.001f,"Left movement works");
            cam=g.gameCamera.transform.position.y;Set(g,"root",.6f);g.Tick(.1f,Vector2.zero);check(g.gameCamera.transform.position.y>cam,"Camera advances independently during stun");Set(g,"root",0f);for(int i=0;i<45;i++)g.Tick(.1f,Vector2.right);check(g.player.position.x<=6.7f,"Horizontal map boundary enforced");for(int i=0;i<45;i++)g.Tick(.1f,Vector2.down);check(g.player.position.y>=g.gameCamera.transform.position.y-3.8f-.001f,"Player stays above lower HUD and within moving viewport");
            Quiet(g);var flame=g.entities.First(e=>e.kind==FastingTopDownEntity.Kind.Flame);g.Collect(flame);ui.Refresh();check(g.FlameStacks==1&&Mathf.Abs(ui.ring.fill-1f/3)<.001f&&!g.FeverActive,"First fire fills one third of portrait ring");g.Collect(flame);ui.Refresh();check(g.FlameStacks==2&&Mathf.Abs(ui.ring.fill-2f/3)<.001f,"Second fire fills two thirds");g.Collect(flame);ui.Refresh();check(g.FeverActive&&ui.feverFlame.gameObject.activeSelf&&Mathf.Abs(ui.ring.fill-1)<.001f,"Third fire starts fever and portrait flame");
            var beforeSprite=ui.feverFlame.sprite;for(int watch=0;watch<20&&ui.feverFlame.sprite==beforeSprite;watch++)await Wait(.04f);check(ui.feverFlame.sprite!=beforeSprite,"Fever fire animates through user sprite frames");for(int i=0;i<25;i++)g.Tick(.1f,Vector2.zero);ui.Refresh();check(g.FeverActive&&ui.ring.fill>.45f&&ui.ring.fill<.55f,"Fever ring drains with remaining duration");for(int i=0;i<27;i++)g.Tick(.1f,Vector2.zero);ui.Refresh();check(!g.FeverActive&&g.FlameStacks==0&&ui.ring.fill==0&&!ui.feverFlame.gameObject.activeSelf,"Zero ring ends fever and hides fire");
            Set(g,"Health",3.5f);Set(g,"Prayer",75f);g.Refresh();ui.Refresh();check(Mathf.Abs(ui.healthFill.fillAmount-.7f)<.001f&&ui.healthText.text.Contains("3.5"),"Health bar displays fractional health");check(Mathf.Abs(g.prayerFill.fillAmount-.375f)<.001f&&ui.prayerText.text.Contains("75"),"Prayer bar displays live prayer");
            var hazard=UnityEngine.Object.Instantiate(g.hazardPrefab);hazard.transform.position=new Vector3(0,9);hazard.UpdateApproach(Vector2.zero);float distant=hazard.body.transform.localScale.x;Vector2 hitSize=hazard.size,groundSize=hazard.footprint.bounds.size;hazard.transform.position=new Vector3(0,1);hazard.UpdateApproach(Vector2.zero);check(hazard.body.transform.localScale.x>distant,"Approaching hazard art grows");check(hazard.size==hitSize&&Vector2.Distance(hazard.footprint.bounds.size,groundSize)<.001f,"Growth leaves visible ground hit area unchanged");UnityEngine.Object.Destroy(hazard.gameObject);
            check(g.entities.Where(e=>e.kind==FastingTopDownEntity.Kind.Flame).All(e=>e.GetComponent<FastingFireSpriteLoop>()&&e.GetComponent<FastingFireSpriteLoop>().frames.Length==4),"All eight fire pickups use user fire animation");
            Quiet(g);g.enabled=true;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;keyboard=InputSystem.AddDevice<Keyboard>();InputSystem.onBeforeUpdate+=queue;InputSystem.onAfterUpdate+=current;keyboard.MakeCurrent();held=Key.D;await Wait(.15f);check(g.player.position.x>.05f,"Actual held D moves right");held=Key.W;float upStart=g.player.position.y;await Wait(.15f);check(g.player.position.y>upStart,"Actual W moves forward");held=Key.S;float downStart=g.player.position.y;await Wait(.15f);check(g.player.position.y<downStart,"Actual S moves backward");held=null;g.enabled=false;
            Quiet(g);Set(g,"Health",3.5f);Set(g,"Prayer",75f);g.Collect(flame);g.Collect(flame);g.Refresh();ui.Refresh();g.SpawnWave();Directory.CreateDirectory("Docs/QA/FastingTopDown");ScreenCapture.CaptureScreenshot(Path.GetFullPath("Docs/QA/FastingTopDown/PortraitHUD-Stacks.png"));await Wait(.3f);g.Collect(flame);g.Refresh();ui.Refresh();ScreenCapture.CaptureScreenshot(Path.GetFullPath("Docs/QA/FastingTopDown/PortraitHUD-Fever.png"));await Wait(.3f);File.WriteAllText("Docs/QA/FastingTopDown/PortraitUpdateValidation.txt",log.ToString());return count+" checks passed";
        }finally{held=null;InputSystem.onBeforeUpdate-=queue;InputSystem.onAfterUpdate-=current;if(keyboard!=null)InputSystem.RemoveDevice(keyboard);InputSystem.settings.backgroundBehavior=oldBackground;InputSystem.settings.editorInputBehaviorInPlayMode=oldMode;g.Begin();g.enabled=true;Time.timeScale=1;}
    }
}
